/**
 * Org-level integration API client — sub-PR 11.
 *
 * Single integration today (email). Mirrors the admin-bff JSON shapes
 * exactly so the form can hand the values straight to PATCH without
 * any re-mapping.
 *
 * Conventions match the rest of admin-mfe:
 *   - credentials: "include" (admin session cookie)
 *   - Idempotency-Key on every write
 *   - Errors throw with the upstream message embedded when possible
 *     so the form can surface a useful failure string.
 */

// The full row returned by GET / PATCH. Password fields are NEVER
// in this shape — only the Vault path refs that confirm "a secret is
// stored". The plaintext password fields in the patch body are
// separate (see UpdateEmailIntegrationParams).
export interface EmailIntegration {
  org_id: string;

  smtp_host: string;
  smtp_port: number;
  smtp_username: string;
  smtp_use_tls: boolean;
  smtp_from_address: string;
  smtp_password_vault_path: string;

  imap_host: string;
  imap_port: number;
  imap_username: string;
  imap_use_ssl: boolean;
  imap_folder: string;
  imap_password_vault_path: string;

  updated_at?: string;
  updated_by: string;
}

export interface GetEmailIntegrationResponse {
  present: boolean;
  integration?: EmailIntegration;
}

// PATCH body — every field optional. Empty passwords mean "leave
// existing Vault ref alone".
export interface UpdateEmailIntegrationParams {
  smtp_host?: string;
  smtp_port?: number;
  smtp_username?: string;
  smtp_use_tls?: boolean;
  smtp_from_address?: string;
  smtp_password?: string;

  imap_host?: string;
  imap_port?: number;
  imap_username?: string;
  imap_use_ssl?: boolean;
  imap_folder?: string;
  imap_password?: string;
}

/**
 * Error thrown by updateEmailIntegration when the BFF returns a non-2xx.
 * `status` is the HTTP code — consumers should branch on it (e.g. 403 →
 * "you don't have permission") rather than string-sniffing `.message`,
 * which is upstream-supplied free text and not a stable contract.
 */
export class UpdateEmailIntegrationError extends Error {
  readonly status: number;
  constructor(status: number, message: string) {
    super(message);
    this.name = "UpdateEmailIntegrationError";
    this.status = status;
  }
}

export async function getEmailIntegration(): Promise<GetEmailIntegrationResponse> {
  const r = await fetch(`/api/v1/admin/integrations/email`, {
    credentials: "include",
  });
  if (!r.ok) {
    throw new Error(`getEmailIntegration failed: ${r.status}`);
  }
  const body = (await r.json()) as { data?: GetEmailIntegrationResponse };
  if (!body.data) {
    throw new Error("getEmailIntegration: missing data envelope");
  }
  return body.data;
}

export async function updateEmailIntegration(
  params: UpdateEmailIntegrationParams,
): Promise<EmailIntegration> {
  const r = await fetch(`/api/v1/admin/integrations/email`, {
    method: "PATCH",
    credentials: "include",
    headers: {
      "Content-Type": "application/json",
      "Idempotency-Key": crypto.randomUUID(),
    },
    body: JSON.stringify(params),
  });
  if (!r.ok) {
    let detail = "";
    try {
      const body = (await r.json()) as { error?: { message?: string } };
      detail = body.error?.message ?? "";
    } catch {
      // body wasn't JSON
    }
    throw new UpdateEmailIntegrationError(
      r.status,
      detail
        ? `updateEmailIntegration failed: ${r.status} — ${detail}`
        : `updateEmailIntegration failed: ${r.status}`,
    );
  }
  const body = (await r.json()) as { data?: GetEmailIntegrationResponse };
  if (!body.data?.integration) {
    throw new Error("updateEmailIntegration: missing integration in response");
  }
  return body.data.integration;
}


