/**
 * Memberships read client — Phase 3d.
 *
 * Hits admin-bff GET /api/v1/admin/users/:id/memberships, which forwards
 * to org-svc TenantService.ListMembershipsByUser. RLS at org-svc scopes
 * the result; an empty list is the legitimate "no memberships visible"
 * answer, not an error.
 */

export type MembershipRole = "member" | "admin" | "owner" | "unspecified";

export interface Membership {
  membership_id: string;
  tenant_id: string;
  tenant_name: string;
  tenant_slug: string;
  user_id: string;
  role: MembershipRole;
  created_at: string; // RFC 3339
}

export interface ListMembershipsResult {
  memberships: Membership[];
}

export async function listMembershipsByUser(
  userId: string,
): Promise<ListMembershipsResult> {
  const r = await fetch(
    `/api/v1/admin/users/${encodeURIComponent(userId)}/memberships`,
    { credentials: "include" },
  );
  if (!r.ok) {
    throw new Error(`listMembershipsByUser failed: ${r.status}`);
  }
  const body = (await r.json()) as { data?: ListMembershipsResult };
  if (!body.data) {
    throw new Error("listMembershipsByUser: missing data envelope");
  }
  return body.data;
}


