/**
 * Admin system-health API client — Phase 5, sub-PR 3.
 *
 * Types mirror the §4 JSON contract from the Go handler
 * (services/admin-bff/internal/handlers/system_health.go).
 *
 * Discriminated result type:
 *   { ok: true; health: SystemHealth }
 *   { ok: false; unavailable: true }   — 503 prometheus_unavailable
 *   { ok: false; unavailable: false }  — other non-2xx
 *
 * All boundary values are narrowed from `unknown` — never `any`.
 */

// ── Wire types (mirror Go handler struct field names byte-exact) ──────────────

export type HealthStatus = "operational" | "degraded" | "outage" | "offline";
export type ServiceStatus = "operational" | "degraded" | "offline" | "unknown";
export type DayStatus = "operational" | "degraded" | "outage" | "unknown";

export interface UptimeTile {
  value_pct: number;
  delta_pct: number;
  sparkline: number[];
  status: HealthStatus;
}

export interface LatencyTile {
  value_ms: number;
  delta_ms: number;
  sparkline: number[];
  status: HealthStatus;
}

export interface ErrorRateTile {
  value_pct: number;
  delta_pct: number;
  sparkline: number[];
  status: HealthStatus;
}

export interface ActiveRunsTile {
  value: number;
  delta: number;
  sparkline: number[];
  status: HealthStatus;
}

export interface HeadlineSection {
  uptime: UptimeTile;
  latency: LatencyTile;
  error_rate: ErrorRateTile;
  active_runs: ActiveRunsTile;
}

export interface ServiceEntry {
  name: string;
  vertical: string;
  status: ServiceStatus;
  uptime_pct_7d: number;
  p95_latency_ms: number;
  error_rate_pct: number;
  sparkline_7d: number[];
  version: string;
  last_seen: string;
}

export interface HeatmapDay {
  date: string;
  status: DayStatus;
  uptime_pct: number | null;
}

export interface HistoryEntry {
  name: string;
  days: HeatmapDay[];
}

export interface SystemHealth {
  history_days: number;
  available_days: number;
  generated_at: string;
  headline: HeadlineSection;
  services: ServiceEntry[];
  uptime_history: HistoryEntry[];
  status_page_url: string;
}

// ── Fetch result ──────────────────────────────────────────────────────────────

export type SystemHealthResult =
  | { ok: true; health: SystemHealth }
  | { ok: false; unavailable: true }
  | { ok: false; unavailable: false; message: string };

// ── Type-narrowing helpers (unknown → typed) ──────────────────────────────────

function isObject(v: unknown): v is Record<string, unknown> {
  return typeof v === "object" && v !== null && !Array.isArray(v);
}

function assertSystemHealth(v: unknown): SystemHealth {
  // We trust the backend contract and do a runtime-structural check on the
  // outermost shape — enough to surface contract drift without `any`.
  if (!isObject(v)) throw new Error("system-health: data is not an object");
  if (typeof (v as Record<string, unknown>).history_days !== "number")
    throw new Error("system-health: missing history_days");
  // Cast after structural check — the handler is the source of truth.
  return v as unknown as SystemHealth;
}

// ── Fetch function ────────────────────────────────────────────────────────────

/** GET /api/v1/admin/system-health — platform-tier only. */
export async function fetchSystemHealth(): Promise<SystemHealthResult> {
  let response: Response;
  try {
    response = await fetch("/api/v1/admin/system-health", {
      credentials: "include",
    });
  } catch (e: unknown) {
    return {
      ok: false,
      unavailable: false,
      message: e instanceof Error ? e.message : "network error",
    };
  }

  if (response.status === 503) {
    // Prometheus unavailable — explicit unavailable arm.
    return { ok: false, unavailable: true };
  }

  if (!response.ok) {
    let message = `fetchSystemHealth failed: ${response.status}`;
    try {
      const body = (await response.json()) as unknown;
      if (
        isObject(body) &&
        isObject(body.error) &&
        typeof (body.error as Record<string, unknown>).message === "string"
      ) {
        message = (body.error as Record<string, unknown>).message as string;
      }
    } catch {
      // ignore parse errors
    }
    return { ok: false, unavailable: false, message };
  }

  try {
    const body = (await response.json()) as unknown;
    if (!isObject(body)) throw new Error("response body is not an object");
    const health = assertSystemHealth(
      (body as Record<string, unknown>).data,
    );
    return { ok: true, health };
  } catch (e: unknown) {
    return {
      ok: false,
      unavailable: false,
      message: e instanceof Error ? e.message : "parse error",
    };
  }
}


