/**
 * Tenants/Workspaces read client — Phase 4a.
 *
 * Hits admin-bff GET /api/v1/admin/tenants which forwards to org-svc
 * TenantService.List. RLS at org-svc scopes the result.
 */

import { notifyWorkspacesChanged } from "@omnicore-platform/platform-chrome";

/** Owner block returned alongside each tenant — Phase 4e. The user_id
 *  is always populated when a creator was recorded; display_name +
 *  email may be empty when the user is no longer visible to the
 *  caller (deleted, cross-tenant, or identity-svc unreachable). */
export interface TenantOwner {
  user_id: string;
  display_name?: string;
  email?: string;
}

/** Display-tier status returned by admin-bff. The proto-side state is
 *  the same enum but serialized as lowercase strings on the wire.
 *  Phase 4f. */
export type TenantStatus =
  | "active"
  | "trial"
  | "past_due"
  | "suspended"
  | "unspecified";

export interface AdminTenant {
  id: string;
  parent_id?: string;
  name: string;
  slug: string;
  created_at: string; // RFC 3339
  updated_at: string;
  legacy_id?: string;
  /** Populated by listTenants only. Other reads (getTenant) return 0. */
  member_count?: number;
  /** Phase 4e. Absent for pre-migration / migrator-written tenants. */
  owner?: TenantOwner;
  /** Phase 4f. Always populated by the server. */
  status: TenantStatus;
  /** Phase 4f. RFC-3339 trial expiry; empty when no trial set. */
  trial_ends_at?: string;
  /** Phase 4f. Whole days until trial expires; computed server-side
   *  (round-up) so the count flips the day the trial actually ends.
   *  Only populated when status == "trial". */
  trial_days_remaining?: number;
  /** C7 (story #928). nodeTypes of Studio tools disabled for this org.
   *  Absent / undefined means no tools are disabled (all enabled). */
  disabled_studio_tools?: readonly string[];
  /** C8 (story #929). When true, online-only tools are hidden in Studio.
   *  Absent / undefined is treated as false (online mode). */
  offline_mode?: boolean;
}

export interface ListTenantsResult {
  tenants: AdminTenant[];
  next_page_token: string;
}

export interface ListTenantsParams {
  page_size?: number;
  page_token?: string;
  /** Tri-state:
   *  - undefined → no filter (all tenants)
   *  - ""        → root tenants only
   *  - "<uuid>"  → children of that tenant
   */
  parent_id?: string;
}

export interface UpdateTenantParams {
  /** Optional; omit to leave unchanged. Empty strings are rejected. */
  name?: string;
  /** Optional; omit to leave unchanged. Empty strings are rejected. */
  slug?: string;
  /** C7 (story #928). nodeTypes of Studio tools to disable for this org.
   *  When combined with clear_disabled_studio_tools=true the full list is
   *  replaced atomically (an empty array clears all disabled tools). */
  disabled_studio_tools?: readonly string[];
  /** When true the server replaces the full disabled_studio_tools list.
   *  Must be true for a no-op empty-array clear to take effect. */
  clear_disabled_studio_tools?: boolean;
  /** C8 (story #929). When present, sets the org-wide offline mode flag. */
  offline_mode?: boolean;
}

export interface CreateTenantParams {
  name: string;
  slug: string;
  /** Optional UUID of the parent tenant. Omit (or undefined) for root. */
  parent_id?: string;
  /** When true, the server validates without writing. The returned
   *  `tenant.id` will be the zero UUID and `dry_run_planned` is true. */
  dry_run?: boolean;
  /** Phase 4f. > 0 sets a trial period at insert time (days). 30/90/180
   *  are the canonical admin-mfe options; server caps at 365. */
  trial_days?: number;
}

export interface CreateTenantResult {
  tenant: AdminTenant;
  dry_run_planned: boolean;
}

/** POST /api/v1/admin/tenants — Phase 4c. */
export async function createTenant(
  params: CreateTenantParams,
): Promise<CreateTenantResult> {
  const r = await fetch(`/api/v1/admin/tenants`, {
    method: "POST",
    credentials: "include",
    headers: {
      "Content-Type": "application/json",
      "Idempotency-Key": crypto.randomUUID(),
    },
    body: JSON.stringify(params),
  });
  if (!r.ok) {
    let detail = "";
    try {
      const body = (await r.json()) as { error?: { message?: string } };
      detail = body.error?.message ?? "";
    } catch {
      // body wasn't JSON — keep detail blank
    }
    throw new Error(
      detail
        ? `createTenant failed: ${r.status} — ${detail}`
        : `createTenant failed: ${r.status}`,
    );
  }
  const body = (await r.json()) as { data?: CreateTenantResult };
  if (!body.data) {
    throw new Error("createTenant: missing data envelope");
  }
  // Notify the workspace switcher (and any other useWorkspaceList caller)
  // so the menu picks up the new workspace without a page reload. Skip on
  // dry-run since no row was actually inserted.
  if (!body.data.dry_run_planned) {
    notifyWorkspacesChanged();
  }
  return body.data;
}

/**
 * Error thrown by getTenant when the BFF returns a non-2xx. `status` is the
 * HTTP code; consumers should localize their error UI using
 * `m.workspaces_load_failed({ status })`, not display `.message` directly.
 */
export class GetTenantError extends Error {
  readonly status: number;
  constructor(status: number) {
    super(`getTenant failed: ${status}`);
    this.name = "GetTenantError";
    this.status = status;
  }
}

/** GET /api/v1/admin/tenants/:id — Phase 4b. */
export async function getTenant(id: string): Promise<AdminTenant> {
  const r = await fetch(`/api/v1/admin/tenants/${encodeURIComponent(id)}`, {
    credentials: "include",
  });
  if (!r.ok) {
    throw new GetTenantError(r.status);
  }
  const body = (await r.json()) as { data?: AdminTenant };
  if (!body.data) {
    throw new Error("getTenant: missing data envelope");
  }
  return body.data;
}

/** PATCH /api/v1/admin/tenants/:id — Phase 4b. Returns post-image. */
export async function updateTenant(
  id: string,
  params: UpdateTenantParams,
): Promise<AdminTenant> {
  const r = await fetch(`/api/v1/admin/tenants/${encodeURIComponent(id)}`, {
    method: "PATCH",
    credentials: "include",
    headers: {
      "Content-Type": "application/json",
      "Idempotency-Key": crypto.randomUUID(),
    },
    body: JSON.stringify(params),
  });
  if (!r.ok) {
    let detail = "";
    try {
