/**
 * Admin API-keys client — Phase E.
 *
 * Hits admin-bff /api/v1/admin/api-keys which forwards to identity-svc
 * ApiKeyService. RLS at identity-svc scopes the result to the caller's org.
 *
 * The plaintext secret is only ever present in the IssuedApiKey envelope
 * returned by issue/rotate — it is shown once and never persisted in the
 * MFE. List responses carry only token_prefix + last_four for masking.
 */

export type ApiKeyAccessLevel = "read_only" | "read_write";
export type ApiKeyStatus = "active" | "expired" | "revoked";

export interface ApiKey {
  id: string;
  name: string;
  token_prefix: string;
  last_four: string;
  access_level: ApiKeyAccessLevel;
  status: ApiKeyStatus;
  created_by_email: string;
  created_at: string;
  expires_at: string | null;
  last_used_at: string | null;
  revoked_at: string | null;
}

export interface IssueApiKeyParams {
  name: string;
  access_level: ApiKeyAccessLevel;
  expires_at?: string | null;
}

export interface IssuedApiKey {
  key: ApiKey;
  secret: string;
}

/** GET /api/v1/admin/api-keys — list the org's keys (masked). */
export async function listApiKeys(): Promise<ApiKey[]> {
  const r = await fetch("/api/v1/admin/api-keys", { credentials: "include" });
  if (!r.ok) throw new Error(`listApiKeys failed: ${r.status}`);
  const body = (await r.json()) as { data?: { api_keys?: ApiKey[] } };
  return body.data?.api_keys ?? [];
}

/** POST /api/v1/admin/api-keys — issue a new key. Response carries the
 *  one-time plaintext secret. */
export async function issueApiKey(
  params: IssueApiKeyParams,
): Promise<IssuedApiKey> {
  const r = await fetch("/api/v1/admin/api-keys", {
    method: "POST",
    credentials: "include",
    headers: {
      "Content-Type": "application/json",
      "Idempotency-Key": crypto.randomUUID(),
    },
    body: JSON.stringify(params),
  });
  if (!r.ok) throw new Error(await errDetail(r, "issueApiKey"));
  const body = (await r.json()) as { data?: IssuedApiKey };
  if (!body.data) throw new Error("issueApiKey: missing data envelope");
  return body.data;
}

/** POST /api/v1/admin/api-keys/:id/rotate — replace the secret. Response
 *  carries the new one-time plaintext secret. */
export async function rotateApiKey(id: string): Promise<IssuedApiKey> {
  const r = await fetch(`/api/v1/admin/api-keys/${id}/rotate`, {
    method: "POST",
    credentials: "include",
    headers: { "Idempotency-Key": crypto.randomUUID() },
