/**
 * Platform AI-provider key API client (#2531).
 *
 * Mirrors src/api/integrations.ts. These are PLATFORM-wide keys (Serper,
 * Apify, Jina) shared across every tool, not org-scoped integrations — but
 * the admin-bff wire conventions are identical:
 *
 *   - credentials: "include" (admin session cookie)
 *   - Idempotency-Key on every write (PUT)
 *   - The raw API key is NEVER returned; only presence/metadata.
 *   - Errors throw a typed ProviderKeyError carrying the HTTP status so the
 *     UI can branch on 403 (not a platform admin) without string-sniffing.
 *
 * Endpoints (admin-bff, #2530):
 *   GET  /api/v1/admin/integrations/providers            → {data:{providers:[…]}}
 *   PUT  /api/v1/admin/integrations/providers/{provider} → {data:{provider:{…}}}
 */

// One provider's presence/metadata as projected by admin-bff. The raw secret
// and Vault path are DELIBERATELY absent from the wire shape. updated_at is
// null (→ undefined here) when the provider has never been configured.
export interface ProviderKey {
  provider: string;
  configured: boolean;
  updated_at?: string | null;
  updated_by: string;
  updated_by_name: string;
}

/**
 * Error thrown by the provider-key client when the BFF returns a non-2xx.
 * `status` is the HTTP code — consumers MUST branch on it (e.g. 403 → "platform
 * admin only") rather than string-sniffing `.message`, which is upstream-supplied
 * free text and not a stable contract.
 */
export class ProviderKeyError extends Error {
  readonly status: number;
  constructor(status: number, message: string) {
    super(message);
    this.name = "ProviderKeyError";
    this.status = status;
  }
}

// Best-effort extraction of the upstream error message from a non-2xx body,
// so a thrown ProviderKeyError can carry a useful detail string.
async function readErrorDetail(r: Response): Promise<string> {
  try {
    const body = (await r.json()) as { error?: { message?: string } };
    return body.error?.message ?? "";
  } catch {
    return "";
  }
}

/**
 * List presence/metadata for every known AI provider. Always resolves to an
 * array (empty when none configured). Throws {@link ProviderKeyError} on a
 * non-2xx response.
 */
export async function listProviderKeys(): Promise<ProviderKey[]> {
  const r = await fetch(`/api/v1/admin/integrations/providers`, {
    credentials: "include",
  });
  if (!r.ok) {
    const detail = await readErrorDetail(r);
    throw new ProviderKeyError(
      r.status,
      detail
        ? `listProviderKeys failed: ${r.status} — ${detail}`
        : `listProviderKeys failed: ${r.status}`,
    );
  }
  const body = (await r.json()) as { data?: { providers?: ProviderKey[] } };
  if (!body.data?.providers) {
    throw new Error("listProviderKeys: missing data.providers envelope");
  }
  return body.data.providers;
}

/**
 * Store one provider's API key. An empty `apiKey` preserves the existing stored
 * key (the BFF treats "" as "leave the Vault ref untouched"). Returns the
 * post-image metadata; the raw key is never echoed back. Throws
 * {@link ProviderKeyError} on a non-2xx response (e.g. 400 unknown provider,
 * 403 not a platform admin).
 */
export async function setProviderKey(
  provider: string,
  apiKey: string,
): Promise<ProviderKey> {
  const r = await fetch(`/api/v1/admin/integrations/providers/${provider}`, {
    method: "PUT",
    credentials: "include",
    headers: {
      "Content-Type": "application/json",
      "Idempotency-Key": crypto.randomUUID(),
    },
    body: JSON.stringify({ api_key: apiKey }),
  });
  if (!r.ok) {
    const detail = await readErrorDetail(r);
    throw new ProviderKeyError(
      r.status,
      detail
        ? `setProviderKey failed: ${r.status} — ${detail}`
        : `setProviderKey failed: ${r.status}`,
    );
  }
  const body = (await r.json()) as { data?: { provider?: ProviderKey } };
  if (!body.data?.provider) {
    throw new Error("setProviderKey: missing data.provider in response");
  }
  return body.data.provider;
}


