 * admin-bff returns — see services/admin-bff/internal/handlers/users.go.
 *
 * The BFF wraps every response in `{data: ..., error?: ...}`. Callers
 * receive a flat `ListUsersResult`; the envelope is unwrapped here.
 */

export type UserStatus =
  | "active"
