/** PATCH /api/v1/admin/users/:id — Phase 3b edit path. Returns the
 *  post-image so callers can swap their local cache without a
 *  follow-up GET. */
export async function updateUser(
  id: string,
  params: UpdateUserParams,
): Promise<AdminUser> {
  const r = await fetch(`/api/v1/admin/users/${encodeURIComponent(id)}`, {
    method: "PATCH",
    credentials: "include",
    headers: {
      "Content-Type": "application/json",
      // PATCH mutates state; admin-bff requires Idempotency-Key on
      // every write so retries de-dupe via NATS KV.
      "Idempotency-Key": crypto.randomUUID(),
    },
    body: JSON.stringify(params),
  });
  if (!r.ok) {
    let detail = "";
    try {
      const body = (await r.json()) as { error?: { message?: string } };
      detail = body.error?.message ?? "";
    } catch {
      // body wasn't JSON — keep detail blank
    }
    throw new Error(
      detail
        ? `updateUser failed: ${r.status} — ${detail}`
        : `updateUser failed: ${r.status}`,
    );
  }
  const body = (await r.json()) as { data?: AdminUser };
  if (!body.data) {
    throw new Error("updateUser: missing data envelope");
  }
  return body.data;
}

/**
 * Shared status-flip helper for the two Phase 3c endpoints. The BFF maps
 * both to gRPC writes, returns the post-image in the `{data}` envelope,
 * and surfaces grpc errors as `{error: {code, message}}` on non-2xx.
 */
async function flipStatus(
  id: string,
  action: "suspend" | "reactivate",
): Promise<AdminUser> {
  const r = await fetch(
    `/api/v1/admin/users/${encodeURIComponent(id)}/${action}`,
    {
      method: "POST",
      credentials: "include",
      headers: {
        "Content-Type": "application/json",
        "Idempotency-Key": crypto.randomUUID(),
      },
    },
  );
  if (!r.ok) {
    let detail = "";
    try {
      const body = (await r.json()) as { error?: { message?: string } };
      detail = body.error?.message ?? "";
    } catch {
      // body wasn't JSON — keep detail blank
    }
    throw new Error(
      detail
        ? `${action}User failed: ${r.status} — ${detail}`
        : `${action}User failed: ${r.status}`,
    );
  }
  const body = (await r.json()) as { data?: AdminUser };
  if (!body.data) {
    throw new Error(`${action}User: missing data envelope`);
  }
  return body.data;
}

/** POST /api/v1/admin/users/:id/suspend — Phase 3c. Returns post-image. */
export async function suspendUser(id: string): Promise<AdminUser> {
  return flipStatus(id, "suspend");
}

/** POST /api/v1/admin/users/:id/reactivate — Phase 3c. Returns post-image. */
export async function reactivateUser(id: string): Promise<AdminUser> {
  return flipStatus(id, "reactivate");
}

export async function listUsers(
  params: ListUsersParams = {},
): Promise<ListUsersResult> {
  const qp = new URLSearchParams();
  if (params.cursor) qp.set("cursor", params.cursor);
  if (params.limit !== undefined) qp.set("limit", String(params.limit));
  const q = qp.toString();
  const url = q
    ? `/api/v1/admin/users?${q}`
    : "/api/v1/admin/users";

  const r = await fetch(url, { credentials: "include" });
  if (!r.ok) {
    throw new Error(`listUsers failed: ${r.status}`);
  }
  const body = (await r.json()) as {
    data?: ListUsersResult;
  };
  if (!body.data) {
    throw new Error("listUsers: missing data envelope");
  }
  return body.data;
}



